// org.client.list — generated by `pnpm gen:query org client-list`. Read through ../repository.ts; RLS limits the
// rows to what the actor may see. Queries run read-only (02-architecture §3).
import { z } from 'zod';
import { defineQuery } from '../../kernel/index.ts';
import { orgPermissions } from '../permissions.ts';

export const clientList = defineQuery({
  name: 'org.client.list',
  permission: orgPermissions.clientList,
  input: z.object({}),
  handle: () => Promise.resolve<{ id: string }[]>([]),
});
